$stmt=$db->prepare("SELECT n.*,o.order_number,o.public_token FROM customer_notifications n LEFT JOIN online_orders o ON o.id=n.order_id WHERE n.customer_id=? ORDER BY n.id DESC LIMIT 100");$stmt->execute([$cid]);$rows=$stmt->fetchAll()?:[];$db->prepare("UPDATE customer_notifications SET is_read=1 WHERE customer_id=?")->execute([$cid]);$pageTitle='Notifikasi';$activePage='account';require __DIR__.'/_header.php';
